  const startNavBadges = () => { try { paintNavBadges(JSON.parse(sessionStorage.getItem(adminBadgeStorageKey) || '{}')); } catch (_) {} const refreshedAt = Number(sessionStorage.getItem(adminBadgeRefreshKey) || 0); if (document.hidden || Date.now() - refreshedAt < adminBadgeTtlMs) return; setTimeout(async () => { try { const [orders, finance, notifications] = await Promise.all([countRows('delivery_orders?select=id&status=neq.สำเร็จแล้ว', M.requestCount, 'admin-nav:orders'), countRows('withdrawal_requests?select=id&status=eq.pending', M.requestCount, 'admin-nav:finance').catch(() => 0), countRows('mobile_notifications?select=id&status=eq.pending', M.requestCount, 'admin-nav:notifications').catch(() => 0)]); const values = { orders, finance, notifications }; paintNavBadges(values); sessionStorage.setItem(adminBadgeStorageKey, JSON.stringify(values)); sessionStorage.setItem(adminBadgeRefreshKey, String(Date.now())); } catch (_) { /* Cached values remain visible; badge failures never block a route. */ } }, 0); };
