        try { await M.request('platform_configs?on_conflict=key', { method: 'POST', private: true, headers: { Prefer: 'resolution=merge-duplicates,return=minimal' }, body: JSON.stringify({ key: 'business_rules', value, updated_at: M.ui.nowIso() }) }); M.ui.setNotice('บันทึกกติกาธุรกิจกลางแล้ว'); } catch (err) { M.ui.setNotice(err.message, 'error'); }
